# O'Hare: the airport moves off the lakefront onto open land north-west of the city, beyond the interstate. An airport expressway leaves the outer
# junction of the 'Wrigley' interchange (so it is one slip road away from the interstate) and ends in a loop road past the terminal.
# (src/airport.js builds the airfield from m['airport'].)  Run after add_port.py.
import json, os
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'src', 'chicago')
m = json.load(open(os.path.join(P, 'mapdata.json')))
m['streets'] = [s for s in m['streets'] if s.get('tag') != 'airport']
ix = next(i for i in m['interchanges'] if i['label'] == 'Wrigley')
J = ix['pts'][0]                                  # the interchange's outer junction (west of the interstate)
RY, X0, X1 = 60, -230, 90                         # the runway: east-west, map px
LY0, LY1, LX0, LX1 = 134, 172, -175, 40           # the terminal loop road (the terminal lies between the runway and its north side)
m['streets'].append({'cls': 'six', 'tag': 'airport', 'name': 'Airport Expressway', 'pts': [J, [200, 228], [150, 185], [95, 158], [LX1, 153]]})
m['streets'].append({'cls': 'four', 'tag': 'airport', 'name': 'Terminal Loop', 'pts': [[LX1, 153], [LX1, LY0], [LX0, LY0], [LX0, LY1], [LX1, LY1], [LX1, 153]]})
m['airport'] = {'name': "O'Hare", 'dest': 'sf', 'at': [(LX0 + LX1) / 2, LY0], 'rwy': [[X0, RY], [X1, RY]], 'width': 30, 'y': 0.17, 'apronSide': 1, 'num0': '09', 'num1': '27'}
json.dump(m, open(os.path.join(P, 'mapdata.json'), 'w'))
open(os.path.join(P, 'mapdata.js'), 'w').write('// generated by tools/build_mapdata.py + add_black_roads.py + add_pier_roads.py + add_port.py + add_airport.py (same content as mapdata.json) - edit the map in the studio, or re-run the tools\nexport default ' + json.dumps(m) + ';\n')
print('airport moved to', m['airport']['at'])
